    private static readonly Dictionary<string, Geometry> Cache = new();

    /// <summary>取图标 Geometry；未知 token 回退到 info。</summary>
    public static Geometry Get(string? token)
    {
        token = token?.ToLowerInvariant();
        if (string.IsNullOrWhiteSpace(token) || !PathData.ContainsKey(token))
            token = "info";
        if (!Cache.TryGetValue(token, out var g))
        {
            // 回退后的 token 必然命中；取不到时给空 Geometry，避免抛异常打断 UI 构建。
            g = PathData.TryGetValue(token, out var d) ? Geometry.Parse(d) : Geometry.Empty;
            Cache[token] = g;
        }
        return g;
    }

    /// <summary>生成描边式 Path 图标（默认白色描边，透明填充）。</summary>
    public static System.Windows.Shapes.Path Make(string? token, double size = 18, Brush? stroke = null)
    {
        return new System.Windows.Shapes.Path
        {
            Data = Get(token),
            Width = size,
            Height = size,
            Stretch = Stretch.Uniform,
            Fill = Brushes.Transparent,
            Stroke = stroke ?? Brushes.White,
            StrokeThickness = 1.8,
            StrokeStartLineCap = PenLineCap.Round,
            StrokeEndLineCap = PenLineCap.Round,
            StrokeLineJoin = PenLineJoin.Round,
            SnapsToDevicePixels = true,
            UseLayoutRounding = true,
            VerticalAlignment = VerticalAlignment.Center
        };
    }
